      'acc.t.ai': "Conectar IA",
      'mcp.lead': "Converse com a sua própria IA sobre o seu estudo: peça uma análise das suas dificuldades, um resumo para as anotações, flashcards, questões, discursivas ou um mapa mental — ela cria tudo direto nos seus tópicos. Ela também monta simulados com as questões do seu banco (sem gastar créditos de IA), analisa os que você fez e corrige as discursivas digitadas. E monta o seu planejamento (ciclo de estudos, metas da semana, grade por dia ou ciclo por questões) pelos seus pontos fracos. Chame o conector sem pedir nada e ele mostra tudo o que dá para fazer.",
