      'mcp.gpt': "No ChatGPT, abra Configurações → Aplicativos e conectores|Ative o modo desenvolvedor (em Avançado) e crie um conector|Cole o endereço, escolha OAuth e autorize com a sua conta",
      'mcp.gemini': "No Gemini: por enquanto, o Google só aceita conectores personalizados em contas pessoais nos Estados Unidos, com o Gemini em inglês, ou no Gemini Enterprise, cadastrados pelo administrador da empresa. Quando o Google liberar em outros lugares, este mesmo endereço deve funcionar.",
      'mcp.can': "Lê seu estudo para analisar, organiza disciplinas, tópicos (move, transforma em pastas) e cadernos, cria e corrige conteúdo e simulados, monta o planejamento e anexa PDFs nos seus tópicos",
