      'qz.delTitleN': "Excluir {0} questões?",
      'qz.delBody': "Ela sai do banco. O histórico de respostas continua contando no acerto do tópico.",
      'qz.pastePh': "@banca CEBRASPE\n@ano 2024\nO ato administrativo goza de presunção de legitimidade.\n= C\n> Presunção relativa: admite prova em contrário.\n---\nSão atributos do ato administrativo, EXCETO:\nA) presunção de legitimidade\nB) imperatividade\nC) autoexecutoriedade\nD) discricionariedade\n= D",
      'qz.fmtTitle': "Como escrever",
      'qz.aiHint': "Quer que uma IA crie as questões? Copie o prompt, cole na IA que você usa junto com o conteúdo e cole a resposta aqui.",
      'qz.aiCopy': "Copiar prompt",
      'qz.aiCopied': "Prompt copiado: cole na sua IA junto com o conteúdo",
      'qz.aiNoTopic': "o assunto do conteúdo abaixo",
      'qz.aiPrompt': "Você é um elaborador de questões de concursos públicos. A partir do CONTEÚDO que está no fim desta mensagem, crie 20 questões inéditas sobre {0}.\n\nResponda SOMENTE com as questões, no formato exato abaixo — sem introdução, sem conclusão, sem markdown, sem negrito e sem numerar as questões —, porque a resposta será colada direto num aplicativo que lê esse formato.\n\nFORMATO\n- Separe cada questão da seguinte com uma linha contendo apenas ---\n- Certo ou Errado: escreva a afirmação e, na linha de baixo, = C (certo) ou = E (errado).\n- Múltipla escolha: o enunciado; depois cada alternativa numa linha começando com A) B) C) D) E); depois o gabarito numa linha = LETRA.\n- Comentário: uma linha começando com > explicando por que o gabarito está certo (e, nas erradas, onde está o erro).\n- Se o conteúdo indicar a banca ou o ano, use no início uma linha @banca NOME e/ou @ano AAAA (valem para as questões seguintes).\n\nCRITÉRIOS\n- Metade Certo/Errado (estilo CEBRASPE) e metade múltipla escolha com 5 alternativas.\n- Cubra os pontos mais cobrados do conteúdo; varie a dificuldade; use as pegadinhas comuns de prova (exceções, prazos, competências, termos absolutos).\n- Equilibre os gabaritos (não deixe quase tudo Certo ou quase tudo a mesma letra).\n- Baseie-se só no conteúdo; não invente números de lei, prazos ou entendimentos que não estejam nele.\n\nEXEMPLO DO FORMATO\n@banca CEBRASPE\nO ato administrativo goza de presunção de legitimidade, que é relativa.\n= C\n> A presunção é relativa (juris tantum): admite prova em contrário.\n---\nSão atributos do ato administrativo, EXCETO:\nA) presunção de legitimidade\nB) imperatividade\nC) autoexecutoriedade\nD) discricionariedade\nE) tipicidade\n= D\n> Discricionariedade não é atributo; é uma característica de alguns atos.\n\nCONTEÚDO\n[cole aqui o texto, resumo, artigo de lei ou anotações]",
      'qz.fmt': "@banca CEBRASPE      metadados: valem para as próximas questões\n@ano 2024            (\"-\" limpa: @banca -)\n@orgao TCU\n@cargo Auditor\n\n@texto Título        um texto que as próximas questões compartilham\n...o texto...\n@fim\n@texto -             encerra o compartilhamento\n\nEnunciado (uma ou mais linhas)\nA) primeira          múltipla escolha\nB) segunda\n= B                  gabarito (letra)\n> comentário         opcional\n---                  separa uma questão da próxima\n\nSem alternativas A) B)…, é Certo/Errado: \"= C\" ou \"= E\".",
