      "fd.terms.title": "Exam candidates' Feed — community rules",
      "fd.terms.intro": "The Feed is a place to share the journey: the routine, the wins, the struggles, the tips. To keep it good for everyone:",
      "fd.terms.r1t": "Respect, always.",
      "fd.terms.r1": "No insults, mockery, harassment, discrimination or attacks on anyone at all — users, teachers, exam boards or candidates.",
      "fd.terms.r2t": "No politics.",
      "fd.terms.r2": "No party-political, electoral or ideological debate. Exam news is fine; campaigning and fighting are not.",
      "fd.terms.r3t": "Only what is yours.",
      "fd.terms.r3": "Don't share copyrighted material: prep-course PDFs and classes, handouts, books, videos, paid commented questions, or links to them. Photos: only yours or ones you're allowed to use.",
      "fd.terms.r4t": "No advertising.",
      "fd.terms.r4": "No selling, promoting courses, group buys, affiliate links, asking for followers or chain posts.",
      "fd.terms.r5t": "No inappropriate content.",
      "fd.terms.r5": "Nothing sexual, violent, illegal or that exposes other people's data (full name, phone, ID, address).",
      "fd.terms.r6t": "Look after yourself.",
      "fd.terms.r6": "Don't post your personal data or where you study.",
      "fd.terms.report": "Any post can be {0} through the ⋯ menu. The team reviews it and may delete the content and suspend whoever breaks the rules, for a while or for good. What you post is seen by every Notes user and is your responsibility.",
