      "mt.connHint": "Through the connector, your own AI (Claude, ChatGPT…) also talks to your mentor, without spending credits: ask \"I want to talk to my mentor\".",
      "mt.guideTitle": "How to build a good context",
      "mt.guide1": "Your mentor only knows what's in here. A good context has:",
      "mt.guideList": "The exam and the role: agency, board, level, number of openings and when the last notice came out|The syllabus, subject by subject, with each one's weight in the exam|The history of what's asked: the topics that come up most, the board's style, common traps|The role's focus: what the job does and what knowledge that requires|The exam format: multiple choice, essay, true or false, pass mark, elimination",
      "mt.guide2": "You can build this text in any AI. Copy the request below, paste it into ChatGPT, Claude or Gemini, change the exam and paste the answer here.",
      "mt.promptText": "Build a complete dossier for an exam mentor about the public exam [EXAM NAME AND ROLE]. Include: 1) agency, board, education level, salary, openings and dates of the last notices; 2) the exam format (multiple choice, essay, true or false, pass mark, elimination rules); 3) the syllabus, subject by subject, with the number of questions or weight of each; 4) the history of what's asked: the topics that came up most in recent exams, the board's style and common traps; 5) the role's focus: what the job does and what it requires; 6) the subjects that fail the most candidates and what a candidate can't leave out. Say what is certain and what is an estimate.",
