      "ref.title": "Refer and earn",
      "ref.heroT": "Recommend GooDraw and earn every month",
      "ref.hero": "Share your link with people studying for public exams. On every Notes Premium payment from whoever subscribes through it, you get 15%, every month, for as long as the subscription lasts.",
      "ref.heroN": "of every payment, every month",
      "ref.s1T": "Create your link",
      "ref.s1": "Pick a code and enter your WhatsApp and Pix key. It works right away, no approval needed.",
      "ref.s2T": "Share it",
      "ref.s2": "Send the link to friends, study groups and followers. Whoever opens it and signs in, or types your code when creating the account, is tied to you.",
      "ref.s3T": "Get paid by Pix",
      "ref.s3": "Each payment earns you 15%, released when the money reaches our account (Pix in 7 days; card in about 30, one installment a month when paid in installments). Every 1st we close the month, send the statement and pay by Pix, from R$ 20.",
      "ref.formT": "I want to be an affiliate",
      "ref.code": "Your code in the link",
      "ref.codeHint": "3 to 32 letters, numbers, - or _. It can't be changed later.",
      "ref.codeFree": "Available.",
      "ref.whatsapp": "WhatsApp",
      "ref.whatsappPh": "+55 51 99999-8888",
      "ref.pix": "Pix key",
      "ref.waHint": "Your WhatsApp lets the team reach you when needed. The Pix key can wait, but without it you can't be paid.",
      "ref.terms": "Programme terms",
      "ref.t1": "The commission is 15% of every GooNotes Premium payment (card or Pix) by whoever came through your link, while the subscription is active: every month or renewal paid earns a new commission.",
      "ref.t2": "Whoever subscribes through your link pays the normal price: the programme gives no discount.",
      "ref.t3": "A person is tied to you when they open your link and then create an account or sign in (within 60 days, on the same device), or when they type your code in \"Who referred you?\", when creating the account or in My account, on any device. The first referral counts: whoever already belongs to another affiliate or partner, or has subscribed before, doesn't change.",
      "ref.t4": "Referring yourself or using your other accounts doesn't count: those subscriptions earn no commission, and abuse ends your participation.",
      "ref.t5": "Each commission is released when the money of that payment reaches GooDraw's account, and never before the 7-day cooling-off period. Pix: on day 7. Card: about 30 days later. Card in installments: one part a month, each when its installment arrives. A refund cancels what wasn't released yet; once released, it's yours, even if the person cancels.",
      "ref.t6": "Every 1st we close what was released up to the end of the previous month. Payment is by Pix, to the key registered here, from R$ 20; below that the balance is kept for the next month.",
      "ref.t7": "Subscriptions made inside the Android app, through Google Play, earn no commission.",
      "ref.t8": "The team may contact you on the WhatsApp you gave. These rules may change with prior notice; commissions already calculated don't change. Being an affiliate doesn't include Notes Premium.",
