      "rv.asA42": "Yes, but I'd accept something more flexible",
      "rv.asA43": "Yes, and I want to keep it exactly",
      "rv.asResTitle": "The mode for you",
      "rv.asTag": "★ Suggested for you",
      "rv.asTagRec": "★ Suggested for you · Recommended",
      "rv.asSeeAll": "See the three modes",
      "rv.asPreferAuto": "I prefer Automatic (recommended)",
      "rv.asSnow": "Before you choose: without looking at your performance, the reviews add up and snowball.",
      "rv.asWhy.11": "You study with questions and cards: Notes measures how much you remember and sets the date right.",
      "rv.asWhy.12": "You read or watch a class and then do questions: they show what stuck and help set the date.",
      "rv.asWhy.13": "You study mostly by reading and summarizing: with less practice to measure, the pace you set counts more.",
      "rv.asWhy.21": "You'd rather not worry about dates: Notes decides for you.",
      "rv.asWhy.22": "You want to pick the weekdays and a daily limit: that is what My way does.",
      "rv.asWhy.23": "You want to control the gaps: Notes works out the dates from what you set.",
      "rv.asWhy.31": "Your time varies: Notes spreads the reviews out, so the queue doesn't pile up.",
      "rv.asWhy.32": "You have set days in the week: you can mark only those days.",
      "rv.asWhy.33": "You review every day: Notes brings each topic back at the right time.",
      "rv.asWhy.41": "You don't follow a review table: Notes builds yours from your memory.",
      "rv.asWhy.42": "You follow a table but accept something more flexible: My way lets you adjust the days.",
      "rv.asWhy.43": "You already follow a review table and want to keep it: here the pace is the one you set.",
      "rv.asWhy.auto": "It is what we recommend: Notes sets the date from your memory, with no work on your side.",
      "rv.asWhy.mine": "You set the pace (days, limit, how many times) and Notes builds the schedule.",
      "rv.asWhy.fixed": "You choose the gaps and Notes only works out the dates.",
      "rv.cmpTitle": "How do you want to review?",
      "rv.cmpSub": "Notes has three ways to build your review queue. You use one at a time and can switch whenever you like, with the Mode button in Reviews.",
      "rv.cmpPick": "Review mode",
      "rv.cmpRec": "★ Recommended",
      "rv.cmpSemi": "Semi-automatic",
      "rv.cmpLow": "Least recommended",
      "rv.cmpManual": "100% manual",
      "rv.cmpNow": "In use",
      "rv.cmpWork": "Your effort",
      "rv.cmpWorkN": "{0} of 3",
      "rv.cmpPros": "Pros",
      "rv.cmpCons": "Cons",
      "rv.cmpAutoOne": "Notes decides when each topic comes back, from your memory.",
      "rv.cmpAutoHow": "Each practice (questions, cards, essay) shows how much you remember. Went well, the topic takes longer to come back; got it wrong, it returns sooner. Close to the exam, what weighs most comes first.",
      "rv.cmpAutoP1": "Nothing to set up",
      "rv.cmpAutoP2": "Reviews at the right time: not too early (wasted time), not too late (already forgotten)",
      "rv.cmpAutoP3": "Each topic at its own pace: what you master comes back less",
      "rv.cmpAutoP4": "Reviews are spread out: the queue doesn't pile up",
      "rv.cmpAutoC1": "You don't pick the dates",
      "rv.cmpAutoC2": "Works better if you practice (questions and cards), not just read",
      "rv.cmpWhyT": "Why we recommend it:",
      "rv.cmpWhy": "it is the same method as flashcards, tested on millions of reviews. You remember the same while reviewing less.",
      "rv.cmpMineOne": "You set the pace; Notes builds the schedule.",
      "rv.cmpMineHow": "You answer three questions once: how many times to review each topic before the exam, on which days and how many a day, and who decides the next one. Notes spreads the reviews up to the eve of the exam.",
      "rv.cmpMineP1": "You pick the weekdays and the daily limit",
      "rv.cmpMineP2": "The daily limit holds the queue: it doesn't blow up",
      "rv.cmpMineP3": "You can change a date on the calendar",
      "rv.cmpMineC1": "Less precise than automatic: it looks less at how much you remember of each topic",
      "rv.cmpMineC2": "Works better with the exam date set",
      "rv.cmpFixedOne": "You pick the gaps (1, 7, 15, 30…); Notes only works out the dates.",
      "rv.cmpFixedHow": "Each topic you study follows your sequence: the 1st review in 1 day, the 2nd 7 days later, and so on, counting from the day you reviewed.",
      "rv.cmpFixedP1": "Predictable: you know every date in advance",
      "rv.cmpFixedP2": "Same as the classic schedule method (24h, 7, 30…)",
      "rv.cmpFixedC1": "Doesn't look at your performance: what you master comes back as often as what you get wrong",
      "rv.cmpFixedC2": "**It snowballs.** Each new topic adds reviews to the old ones, and each day missed pushes everything to the next day",
      "rv.cmpSnowT": "Example:",
      "rv.cmpSnow": "5 new topics a day, sequence 1–7–15–30–60. Reviews per day:",
