      'acc.t.ai': "Connect AI",
      'mcp.lead': "Talk to your own AI about your studies: ask for an analysis of your weak spots, a summary for your notes, flashcards, questions, essay questions or a mind map — it creates them right in your topics. It also builds mock exams from your question bank (no AI credits spent), analyses the ones you took and grades your typed essay answers. And it builds your study plan (study cycle, weekly goals, daily timetable or question cycle) around your weak spots. Call the connector without asking anything and it shows everything it can do.",
      'mcp.address': "Connector address",
      'mcp.copy': "Copy",
      'mcp.copied': "Address copied",
      'mcp.claude': "On claude.ai, open Settings → Connectors|Tap “Add custom connector” and paste the address|Click Connect and authorize with your GooNotes account",
      'mcp.gpt': "In ChatGPT, open Settings → Apps & connectors|Turn on developer mode (under Advanced) and create a connector|Paste the address, choose OAuth and authorize with your account",
      'mcp.gemini': "Gemini: for now, Google only accepts custom connectors on personal accounts in the United States, with Gemini in English, or in Gemini Enterprise, added by the company's administrator. When Google opens it up elsewhere, this same address should work.",
      'mcp.can': "Reads your studies to analyse them, organizes subjects, topics (moves them, turns them into folders) and notebooks, creates and fixes content and mock exams, builds the study plan and attaches PDFs in your topics",
