      'qz.delBody': "It leaves the bank. Its answers still count in the topic's accuracy.",
      'qz.pastePh': "@banca CEBRASPE\n@ano 2024\nAdministrative acts are presumed legitimate.\n= C\n---\nWhich is NOT an attribute of the act?\nA) legitimacy\nB) imperativeness\nC) self-enforceability\nD) discretion\n= D",
      'qz.fmtTitle': "How to write it",
      'qz.aiHint': "Want an AI to write the questions? Copy the prompt, paste it into the AI you use with the content, and paste the answer here.",
      'qz.aiCopy': "Copy prompt",
      'qz.aiCopied': "Prompt copied: paste it into your AI with the content",
      'qz.aiNoTopic': "the subject of the content below",
      'qz.aiPrompt': "You write exam questions. From the CONTENT at the end of this message, write 20 new questions about {0}.\n\nAnswer ONLY with the questions, exactly in the format below — no introduction, no conclusion, no markdown, no bold, no numbering — because the answer will be pasted straight into an app that reads this format.\n\nFORMAT\n- Separate each question from the next with a line holding only ---\n- True/False: write the statement and, on the line below, = C (true) or = E (false).\n- Multiple choice: the statement; then each option on its own line starting with A) B) C) D) E); then the key on a line = LETTER.\n- Comment: a line starting with > explaining why the key is right (and, for false ones, where the mistake is).\n- If the content names the exam board or the year, start with @banca NAME and/or @ano YYYY (they apply to the questions that follow).\n\nCRITERIA\n- Half true/false and half multiple choice with 5 options.\n- Cover the points most often asked; vary the difficulty; use the usual exam traps (exceptions, deadlines, absolute terms).\n- Balance the keys.\n- Use only the content; don't make up numbers, deadlines or rulings that aren't in it.\n\nFORMAT EXAMPLE\n@banca CEBRASPE\nAn administrative act is presumed lawful, and the presumption is relative.\n= C\n> The presumption is relative: it can be rebutted.\n---\nAll of these are attributes of an administrative act, EXCEPT:\nA) presumption of legitimacy\nB) imperativeness\nC) self-enforceability\nD) discretion\nE) typicality\n= D\n> Discretion isn't an attribute; some acts have it.\n\nCONTENT\n[paste the text, summary, statute or notes here]",
      'qz.fmt': "@banca X   @ano 2024   @orgao Y   @cargo Z   (sticky; \"-\" clears)\n@texto Title … @fim   a shared text (@texto - ends it)\nStatement\nA) …  B) …\n= B          the key\n> comment    optional\n---          next question\nNo A) B) lines: True/False, \"= C\" or \"= E\".",
