      "mt.guideTitle": "Cómo armar un buen contexto",
      "mt.guide1": "Tu mentor solo sabe lo que esté aquí. Un buen contexto tiene:",
      "mt.guideList": "La oposición y el cargo: órgano, tribunal, nivel, cuántas plazas y cuándo fue la última convocatoria|El temario, asignatura por asignatura, con el peso de cada una en el examen|El historial de preguntas: los temas que más caen, el estilo del tribunal, trampas comunes|El enfoque del cargo: lo que hace el funcionario y qué conocimiento pide|El formato del examen: tipo test, discursiva, verdadero o falso, nota mínima, eliminación",
      "mt.guide2": "Puedes armar este texto en cualquier IA. Copia el pedido de abajo, pégalo en ChatGPT, Claude o Gemini, cambia la oposición y pega la respuesta aquí.",
      "mt.promptText": "Arma un dossier completo para un mentor de oposiciones sobre la oposición [NOMBRE DE LA OPOSICIÓN Y CARGO]. Incluye: 1) órgano, tribunal, nivel de estudios, salario, plazas y fechas de las últimas convocatorias; 2) el formato del examen (tipo test, discursiva, verdadero o falso, nota mínima, criterios de eliminación); 3) el temario, asignatura por asignatura, con el número de preguntas o el peso de cada una; 4) el historial: los temas que más cayeron en los últimos exámenes, el estilo del tribunal y las trampas comunes; 5) el enfoque del cargo: qué hace el funcionario y qué exige; 6) las asignaturas que más suspenden y lo que un candidato no puede dejar de dominar. Di qué es seguro y qué es estimación.",
