      "mcp.lead": "Conversa con tu propia IA sobre tu estudio: pide un análisis de tus dificultades, un resumen para las notas, flashcards, preguntas, discursivas o un mapa mental — ella lo crea todo directo en tus temas. También arma simulacros con las preguntas de tu banco (sin gastar créditos de IA), analiza los que hiciste y corrige las discursivas escritas. Y arma tu planificación (ciclo de estudios, metas de la semana, horario por día o ciclo por preguntas) según tus puntos débiles. Llama al conector sin pedir nada y te muestra todo lo que puede hacer.",
