      "ref.terms": "Términos del programa",
      "ref.t1": "La comisión es del 15 % de cada pago de GooNotes Premium (tarjeta o Pix) de quien llegó por tu enlace, mientras la suscripción esté activa: cada mes o renovación pagada genera una nueva comisión.",
      "ref.t2": "Quien se suscribe con tu enlace paga el precio normal: el programa no da descuento.",
      "ref.t3": "La persona queda vinculada a ti cuando abre tu enlace y luego crea o entra en su cuenta (en hasta 60 días, en el mismo dispositivo), o cuando escribe tu código en \"¿Quién te recomendó?\", al crear la cuenta o en Mi cuenta, en cualquier dispositivo. Vale la primera recomendación: quien ya es de otro afiliado o socio, o ya se suscribió antes, no cambia.",
      "ref.t4": "No vale recomendarte a ti mismo ni usar otras cuentas tuyas: esas suscripciones no generan comisión, y el abuso termina la participación.",
      "ref.t5": "Cada comisión se libera cuando el dinero de ese pago entra en la cuenta de GooDraw, y nunca antes de los 7 días de desistimiento. Pix: el día 7. Tarjeta: unos 30 días después. Tarjeta en cuotas: una parte por mes, cada una cuando entra su cuota. Un reembolso anula lo que aún no se liberó; liberada, es tuya, aunque la persona cancele.",
      "ref.t6": "Cada día 1 cerramos lo liberado hasta el final del mes anterior. El pago es por Pix, a la clave registrada aquí, a partir de R$ 20; por debajo, el saldo se guarda para el mes siguiente.",
