      "fd.terms.title": "Feed des candidats aux concours — règles de vie commune",
      "fd.terms.intro": "Le Feed est un lieu pour partager le parcours : la routine, les réussites, les difficultés, les astuces. Pour qu'il reste agréable pour tout le monde :",
      "fd.terms.r1t": "Toujours le respect.",
      "fd.terms.r1": "Pas d'insulte, de moquerie, de harcèlement, de discrimination ni d'attaque contre qui que ce soit — utilisateur, professeur, jury ou candidat.",
      "fd.terms.r2t": "Pas de politique.",
      "fd.terms.r2": "Pas de débat politique partisan, électoral ou idéologique. Les nouvelles des concours, oui ; les campagnes et les disputes, non.",
      "fd.terms.r3t": "Seulement ce qui est à vous.",
      "fd.terms.r3": "Ne partagez pas de contenu protégé par le droit d'auteur : PDF et cours de prépas, polycopiés, livres, vidéos, questions corrigées payantes, ni de liens vers eux. Des photos, seulement les vôtres ou celles que vous pouvez utiliser.",
      "fd.terms.r4t": "Pas de publicité.",
      "fd.terms.r4": "Pas de vente, de promotion de cours, d'achats groupés, de liens d'affiliation, de demandes d'abonnés ni de chaînes.",
      "fd.terms.r5t": "Pas de contenu inapproprié.",
      "fd.terms.r5": "Rien de sexuel, violent, illégal ou qui expose les données d'autres personnes (nom complet, téléphone, pièce d'identité, adresse).",
      "fd.terms.r6t": "Prenez soin de vous.",
      "fd.terms.r6": "Ne publiez pas vos données personnelles ni l'endroit où vous étudiez.",
      "fd.terms.report": "Toute publication peut être {0} via le menu ⋯. L'équipe l'examine et peut supprimer le contenu et suspendre qui enfreint les règles, pour un temps ou définitivement. Ce que vous publiez est vu par tous les utilisateurs de Notes et relève de votre responsabilité.",
