      "mt.onCard": "Mentor : {0}",
      "mt.create": "Créer mon mentor",
      "mt.suggest": "Suggérer un mentor",
      "mt.connHint": "Via le connecteur, votre propre IA (Claude, ChatGPT…) parle aussi à votre mentor, sans dépenser de crédits : demandez « je veux parler à mon mentor ».",
      "mt.guideTitle": "Comment construire un bon contexte",
      "mt.guide1": "Votre mentor ne sait que ce qui est ici. Un bon contexte comprend :",
      "mt.guideList": "Le concours et le poste : administration, jury, niveau, nombre de postes et date du dernier avis|Le programme, matière par matière, avec le poids de chacune|L'historique des questions : les sujets les plus fréquents, le style du jury, les pièges courants|L'orientation du poste : ce que fait l'agent et les connaissances que cela demande|Le format de l'épreuve : QCM, rédaction, vrai ou faux, note minimale, élimination",
      "mt.guide2": "Vous pouvez rédiger ce texte avec n'importe quelle IA. Copiez la demande ci-dessous, collez-la dans ChatGPT, Claude ou Gemini, changez le concours et collez la réponse ici.",
      "mt.promptText": "Rédigez un dossier complet pour un mentor de concours sur le concours [NOM DU CONCOURS ET POSTE]. Incluez : 1) administration, jury, niveau d'études, salaire, postes et dates des derniers avis ; 2) le format des épreuves (QCM, rédaction, vrai ou faux, note minimale, critères d'élimination) ; 3) le programme, matière par matière, avec le nombre de questions ou le poids de chacune ; 4) l'historique : les sujets les plus fréquents aux dernières épreuves, le style du jury et les pièges courants ; 5) l'orientation du poste : ce que fait l'agent et ce que cela exige ; 6) les matières qui éliminent le plus et ce qu'un candidat doit absolument maîtriser. Indiquez ce qui est certain et ce qui est une estimation.",
      "mt.copyPrompt": "Copier la demande",
