      "mt.newChat": "Nouvelle conversation",
      "mt.back": "Mentors",
      "mt.gone": "Ce mentor n'est plus disponible.",
      "mt.hello": "Bonjour ! Je suis {0}. Je peux faire connaissance avec vous et votre routine, analyser votre étude ou construire votre plan. Par où voulez-vous commencer ?",
      "mt.placeholder": "Écrivez à votre mentor…",
      "mt.send": "Envoyer",
      "mt.costHint": "Chaque message utilise des crédits d'IA (vous voyez combien avant). Via le connecteur, avec votre IA, c'est gratuit.",
      "mt.thinking": "Réflexion…",
      "mt.full": "Cette conversation a atteint sa limite. Commencez-en une autre : le mentor se souvient de vous grâce à votre fiche.",
      "mt.busy": "Le mentor est occupé. Réessayez dans un instant ; rien n'a été décompté.",
      "mcp.lead": "Parlez de votre étude avec votre propre IA : demandez une analyse de vos difficultés, un résumé pour vos notes, des flashcards, des questions, des copies ou une carte mentale — elle crée tout directement dans vos sujets. Elle monte aussi des examens blancs avec les questions de votre banque (sans dépenser de crédits d'IA), analyse ceux que vous avez faits et corrige les copies tapées. Et elle construit votre planification (cycle d'études, objectifs de la semaine, emploi du temps par jour ou cycle par questions) selon vos points faibles. Appelez le connecteur sans rien demander et il montre tout ce qu'il sait faire.",
      "mcp.can": "Lit votre étude pour l'analyser, organise matières, sujets (les déplace, les transforme en dossiers) et cahiers, crée et corrige du contenu et des examens blancs, construit la planification et joint des PDF à vos sujets",
      "pl.t.questions": "Cycle par questions",
      "pl.k.questions": "objectifs de questions par tour, ajustés selon vos résultats",
      "pl.d.questions": "Chaque tour a un total de questions, réparti entre les matières selon leur poids à l'examen et vos résultats : là où vous vous trompez le plus, vous avez plus de questions. À la fin du tour, les objectifs s'ajustent tout seuls.",
