      "ref.heroT": "Recommandez GooDraw et gagnez chaque mois",
      "ref.hero": "Partagez votre lien avec ceux qui préparent des concours. Sur chaque paiement de Notes Premium de qui s'abonne par ce lien, vous gagnez 15 %, chaque mois, tant que l'abonnement dure.",
      "ref.heroN": "de chaque paiement, chaque mois",
      "ref.s1T": "Créez votre lien",
      "ref.s1": "Choisissez un code et indiquez votre WhatsApp et votre clé Pix. C'est valable tout de suite, sans validation.",
      "ref.s2T": "Partagez-le",
      "ref.s2": "Envoyez le lien à vos amis, groupes d'étude et abonnés. Qui l'ouvre et se connecte, ou saisit votre code à la création du compte, vous est rattaché.",
      "ref.s3T": "Soyez payé par Pix",
      "ref.s3": "Chaque paiement vous rapporte 15 %, libérés quand l'argent arrive sur notre compte (Pix en 7 jours ; carte en 30 jours environ, une échéance par mois en paiement échelonné). Chaque 1er, nous clôturons le mois, envoyons le relevé et payons par Pix, à partir de 20 R$.",
      "ref.formT": "Je veux devenir affilié",
      "ref.code": "Votre code dans le lien",
      "ref.codeHint": "De 3 à 32 lettres, chiffres, - ou _. Impossible de le changer ensuite.",
