      "ref.pix": "Clé Pix",
      "ref.waHint": "Le WhatsApp permet à l'équipe de vous joindre au besoin. La clé Pix peut attendre, mais sans elle vous ne pouvez pas être payé.",
      "ref.terms": "Conditions du programme",
      "ref.t1": "La commission est de 15 % de chaque paiement de GooNotes Premium (carte ou Pix) de qui est arrivé par votre lien, tant que l'abonnement est actif : chaque mois ou renouvellement payé génère une nouvelle commission.",
      "ref.t2": "Qui s'abonne par votre lien paie le prix normal : le programme ne donne pas de réduction.",
      "ref.t3": "La personne vous est rattachée quand elle ouvre votre lien puis crée un compte ou se connecte (sous 60 jours, sur le même appareil), ou quand elle saisit votre code dans « Qui vous a parrainé ? », à la création du compte ou dans Mon compte, sur n'importe quel appareil. Le premier parrainage compte : qui est déjà rattaché à un autre affilié ou partenaire, ou s'est déjà abonné, ne change pas.",
      "ref.t4": "Se parrainer soi-même ou utiliser ses autres comptes ne compte pas : ces abonnements ne génèrent pas de commission, et l'abus met fin à la participation.",
      "ref.t5": "Chaque commission est libérée quand l'argent de ce paiement arrive sur le compte d'GooDraw, et jamais avant les 7 jours de rétractation. Pix : le 7e jour. Carte : environ 30 jours après. Carte en plusieurs fois : une part par mois, chacune quand son échéance arrive. Un remboursement annule ce qui n'est pas encore libéré ; une fois libérée, elle est à vous, même si la personne résilie.",
      "ref.t6": "Chaque 1er, nous clôturons ce qui a été libéré jusqu'à la fin du mois précédent. Le paiement se fait par Pix, sur la clé enregistrée ici, à partir de 20 R$ ; en dessous, le solde est conservé pour le mois suivant.",
      "ref.t7": "Les abonnements souscrits dans l'app Android, via Google Play, ne génèrent pas de commission.",
      "ref.t8": "L'équipe peut vous contacter sur le WhatsApp indiqué. Ces règles peuvent changer avec un préavis ; les commissions déjà calculées ne changent pas. Être affilié n'inclut pas Notes Premium.",
